#include <iostream>
#include <string>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long cap, rate, q;
    if (!(std::cin >> cap >> rate >> q)) return 0;

    /* Everything in thousandths of a token, so the arithmetic stays exact. */
    const long long cap_m = cap * 1000;
    long long tokens = cap_m;          /* the bucket starts full */
    long long last = 0;
    bool first = true;

    for (long long i = 0; i < q; ++i) {
        long long t, cost;
        if (!(std::cin >> t >> cost)) break;

        if (first) { last = t; first = false; }
        tokens += rate * (t - last);
        if (tokens > cap_m) tokens = cap_m;
        last = t;

        long long need = cost * 1000;
        if (tokens >= need) {
            tokens -= need;
            std::cout << "ALLOW\n";
        } else {
            std::cout << "DENY\n";
        }
    }
    return 0;
}

