const data = readStdin().split(/\s+/).filter(s => s.length > 0);
if (data.length > 0) {
  const cap = Number(data[0]);
  const rate = Number(data[1]);
  const q = Number(data[2]);
  let pos = 3;

  const capM = cap * 1000;   // thousandths of a token, so the maths is exact
  let tokens = capM;         // the bucket starts full
  let last = null;

  for (let i = 0; i < q; i += 1) {
    const t = Number(data[pos]);
    const cost = Number(data[pos + 1]);
    pos += 2;

    if (last === null) last = t;
    tokens = Math.min(capM, tokens + rate * (t - last));
    last = t;

    const need = cost * 1000;
    if (tokens >= need) {
      tokens -= need;
      print('ALLOW');
    } else {
      print('DENY');
    }
  }
}
